import {journeyAudio} from './soundscape.js';
import {destinations,countries,getDestination,announceDestination,extraArchive} from './destinations.js';
import './atlas.css';
import './premium.css';
const $=s=>document.querySelector(s),motion=()=>!window.zrMotionPaused&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
const region=c=>['Norway','Sweden'].includes(c)?'north':['Greece','Italy','Spain','Türkiye'].includes(c)?'mediterranean':['Australia','China','Saudi Arabia','United Arab Emirates','Bangladesh'].includes(c)?'asia-pacific':'europe';
const nearby={Stockholm:'Tromsø',Oslo:'Tromsø',Corfu:'Santorini',Athens:'Santorini',Portsmouth:'London',Basel:'Geneva','Zürich':'Geneva',Frankfurt:'Amsterdam',Hamburg:'Amsterdam',Munich:'Milan',Anacapri:'Milan'};
const grid=$('.atlas__grid');grid.replaceChildren();
document.querySelectorAll('.atlas__filters button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.atlas__filters button').forEach(b=>{b.classList.toggle('is-active',b===button);b.setAttribute('aria-selected',String(b===button));});grid.querySelectorAll('.country-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.region!==button.dataset.filter;});}));
$('.atlas__head .eyebrow').textContent=`${countries.length} countries · ${destinations.length} destinations`;
$('#atlasTitle').innerHTML='One world.<br><em>Many chapters.</em>';
$('.atlas__head>p:not(.eyebrow)').textContent='Choose a country, then explore its cities, personal photographs and documented experiences. One archive. Every frame in its proper place.';
$('.memories__heading>p:last-child').textContent='A country index, not a second photo archive. Select a country to open its cities and memories.';
const film=$('#filmTrack');film.replaceChildren();
countries.forEach((country,i)=>{const cities=destinations.filter(d=>d.country===country),count=cities.reduce((s,d)=>s+d.photos.length,0);const b=document.createElement('button');b.className='atlas-card country-card';b.dataset.region=region(country);b.dataset.country=country;b.innerHTML=`<div class="country-orbit" aria-hidden="true"><i></i><i></i><b>${String(i+1).padStart(2,'0')}</b></div><span>PERSONAL ATLAS / ${cities.length} ${cities.length===1?'CITY':'CITIES'}</span><h3>${country}</h3><p>${count} photographs · Open country ↗</p>`;b.onclick=()=>openCountry(country);grid.append(b);const chip=document.createElement('button');chip.className='country-film';chip.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span><strong>${country}</strong><small>${cities.map(d=>d.city).join(' · ')} ↗</small>`;chip.onclick=()=>openCountry(country);film.append(chip);});
const dialog=document.createElement('dialog');dialog.className='flight-gallery';dialog.setAttribute('aria-labelledby','flightTitle');
dialog.innerHTML=`<header><div><p id="flightCountry"></p><h2 id="flightTitle"></h2></div><button id="flightClose" aria-label="Close gallery">Close ×</button></header><nav class="city-tabs" aria-label="Cities in this country"></nav><div class="city-story"></div><div class="flight-stage"><img id="flightImage" alt=""><button class="flight-prev" aria-label="Previous photo">←</button><button class="flight-next" aria-label="Next photo">→</button></div><div class="flight-copy" aria-live="polite"><span id="flightKind"></span><p id="flightCaption"></p></div><div class="flight-tools"><button id="flightAuto" aria-pressed="false">Play journey</button><button id="flightZoom" aria-pressed="false">Zoom in</button><span id="flightNumber"></span></div><div class="flight-thumbs" aria-label="Choose a photograph"></div><section class="city-evidence"></section>`;
document.body.append(dialog);
const img=$('#flightImage'),stage=dialog.querySelector('.flight-stage');
let frames=[],index=0,auto=null,zoom=false,drag=null,pan={x:0,y:0},returnFocus=null,currentCity=null,closing=false;
function stop(){clearInterval(auto);auto=null;$('#flightAuto').textContent='Play journey';$('#flightAuto').setAttribute('aria-pressed','false');}
function roll(el,close=false){if(!motion()||currentCity?.sacred)return Promise.resolve();return el.animate(close?[{opacity:1,transform:'perspective(1000px) rotateX(0)'},{opacity:0,transform:'perspective(1000px) rotateX(-12deg) translateY(32px) scaleY(.8)'}]:[{opacity:0,transform:'perspective(1000px) rotateX(14deg) translateY(24px) scaleY(.82)'},{opacity:1,transform:'perspective(1000px) rotateX(0) translateY(0) scaleY(1)'}],{duration:close?180:400,easing:'cubic-bezier(.2,.8,.2,1)'}).finished.catch(()=>{});}
function setZoom(value){zoom=value;pan={x:0,y:0};img.style.transform=value?'scale(2)':'none';stage.classList.toggle('is-zoomed',value);$('#flightZoom').textContent=value?'Zoom out':'Zoom in';$('#flightZoom').setAttribute('aria-pressed',String(value));}
function show(i){if(!frames.length)return;index=(i+frames.length)%frames.length;setZoom(false);const f=frames[index];img.src=f.src;img.alt=f.caption;$('#flightCaption').textContent=f.caption;$('#flightKind').textContent=f.kind;$('#flightNumber').textContent=`${index+1} / ${frames.length}`;dialog.querySelectorAll('.flight-thumbs button').forEach((b,j)=>b.setAttribute('aria-current',String(j===index)));roll(img);if(!currentCity?.sacred)journeyAudio.play('photo-discover',.22);}
function populate(items){stop();frames=[...new Map(items.map(p=>[p.src,p])).values()];const thumbs=dialog.querySelector('.flight-thumbs');thumbs.replaceChildren();stage.hidden=!frames.length;$('.flight-tools').hidden=!frames.length;$('.flight-copy').hidden=!frames.length;frames.forEach((f,i)=>{const b=document.createElement('button');b.setAttribute('aria-label','View photograph '+(i+1));const im=new Image();im.src=f.src;im.alt='';im.loading='lazy';b.append(im);b.onclick=()=>{stop();show(i);};thumbs.append(b);});$('#flightAuto').disabled=frames.length<2;dialog.querySelectorAll('.flight-prev,.flight-next').forEach(b=>b.disabled=frames.length<2);if(frames.length)show(0);}
function open(){closing=false;if(!dialog.open){returnFocus=document.activeElement;dialog.showModal();document.body.classList.add('gallery-open');roll(dialog);$('#flightClose').focus();}dialog.scrollTop=0;journeyAudio.mix();}
function evidence(d){const el=dialog.querySelector('.city-evidence');el.replaceChildren();const facts=[];if(d.city==='London')facts.push(['Education','MSc Computer Science · University of East London · Distinction.'],['Professional chapter','Cybersecurity Engineer at NCC Group.'],['Seasonal umpiring','Last Man Stands, England · recorded as ZR Saimon (LS).']);if(d.city==='Portsmouth')facts.push(['Education','MSc Cybersecurity & Forensic IT · University of Portsmouth.']);if(d.city==='Dhaka')facts.push(['Education','BSc Computer Science & Engineering · AIUB.']);if(d.sacred)facts.push(['Spiritual journey',d.story]);for(const [title,copy] of facts){const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=copy;a.append(h,p);el.append(a);}document.querySelectorAll('.conference-card').forEach(card=>{const location=card.querySelector('.conference-card__top p')?.textContent||'';if(!location.toLowerCase().includes(d.city.toLowerCase()))return;const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p'),b=document.createElement('button');h.textContent=card.querySelector('h3').textContent;p.textContent=location+' · Supplied event-ticket archive';b.textContent='View event evidence ↗';b.onclick=()=>card.querySelector('.ticket-open').click();a.append(h,p,b);el.append(a);});if(d.city==='London'){const a=document.createElement('a');a.href='https://www.lastmanstands.com/lms-cricket/match-centre/info/459959';a.target='_blank';a.rel='noopener';a.textContent='Official LMS umpiring match record ↗';el.append(a);}}
function tabs(country,selected){const nav=dialog.querySelector('.city-tabs');nav.replaceChildren();destinations.filter(d=>d.country===country).forEach(d=>{const b=document.createElement('button');b.textContent=d.city;b.setAttribute('aria-current',String(d.city===selected));b.onclick=()=>openCity(d.city);nav.append(b);});}
function openCity(name){const d=getDestination(name);if(!d)return;currentCity=d;announceDestination(d.city);$('#flightTitle').textContent=d.city;$('#flightCountry').textContent=d.country;tabs(d.country,d.city);const story=dialog.querySelector('.city-story');story.textContent=d.story;populate(d.photos);if(!d.photos.length){const p=document.createElement('p');p.className='archive-note';p.textContent='No city-specific personal photograph in this collection yet.';story.append(p);if(nearby[d.city]){const b=document.createElement('button');b.textContent=`Explore ${nearby[d.city]} photographs instead ↗`;b.onclick=()=>openCity(nearby[d.city]);story.append(b);}}evidence(d);open();}
function openCountry(country){const first=destinations.find(d=>d.country===country);if(first)openCity(first.city);if(country==='Türkiye'&&extraArchive.Türkiye.length){const b=document.createElement('button');b.textContent='Türkiye · other memories';b.onclick=()=>window.zrOpenGallery('Türkiye',extraArchive.Türkiye,'Türkiye');dialog.querySelector('.city-tabs').append(b);}}
window.zrOpenCity=openCity;window.zrOpenCountry=openCountry;
window.zrOpenGallery=(title,items,country='Personal archive')=>{const d=getDestination(title);if(d){openCity(d.city);return;}currentCity=null;$('#flightTitle').textContent=title;$('#flightCountry').textContent=country;dialog.querySelector('.city-tabs').replaceChildren();dialog.querySelector('.city-story').textContent='';dialog.querySelector('.city-evidence').replaceChildren();populate(items);open();};
async function close(){if(closing)return;closing=true;stop();journeyAudio.play('ui-close',.2);await roll(dialog,true);dialog.close();closing=false;}
$('#flightClose').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>{stop();document.body.classList.remove('gallery-open');journeyAudio.mix();returnFocus?.focus({preventScroll:true});});
dialog.querySelector('.flight-prev').onclick=()=>{stop();show(index-1);};dialog.querySelector('.flight-next').onclick=()=>{stop();show(index+1);};$('#flightZoom').onclick=()=>{stop();setZoom(!zoom);};img.ondblclick=()=>setZoom(!zoom);
$('#flightAuto').onclick=()=>{if(auto){stop();return;}if(frames.length<2)return;auto=setInterval(()=>{if(!document.hidden&&!window.zrMotionPaused)show(index+1);},4500);$('#flightAuto').textContent='Pause journey';$('#flightAuto').setAttribute('aria-pressed','true');};
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stop();show(index+(e.key==='ArrowRight'?1:-1));}});stage.addEventListener('pointerdown',e=>{if(e.target!==img)return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointermove',e=>{if(!drag||!zoom)return;pan.x=Math.max(-stage.clientWidth/2,Math.min(stage.clientWidth/2,drag.px+e.clientX-drag.x));pan.y=Math.max(-stage.clientHeight/2,Math.min(stage.clientHeight/2,drag.py+e.clientY-drag.y));img.style.transform=`translate(${pan.x}px,${pan.y}px) scale(2)`;});stage.addEventListener('pointerup',e=>{if(drag&&!zoom&&Math.abs(e.clientX-drag.x)>50){stop();show(index+(e.clientX<drag.x?1:-1));}drag=null;});stage.addEventListener('pointercancel',()=>drag=null);
const soundPanel=document.createElement('div');soundPanel.className='audio-panel';soundPanel.innerHTML='<label>Sound level <input type="range" min="0" max="100" data-sound-volume aria-label="Sound volume"></label><span data-sound-status aria-live="polite"></span>';$('.world-tools').after(soundPanel);journeyAudio.bindControls();
const terminal=$('.terminal__bar');terminal.querySelectorAll('i').forEach(i=>i.remove());const secure=document.createElement('dialog');secure.className='secure-dialog';secure.innerHTML='<button class="secure-close">Close ×</button><p class="eyebrow">SECURE SESSION</p><h2></h2><p class="secure-copy"></p><button class="secure-next">Next step →</button>';document.body.append(secure);const steps=[['Understand','Identify assets, understand risks and establish context before choosing controls.'],['Protect','Use layered safeguards, clear access boundaries and responsible engineering.'],['Verify','Test assumptions, review evidence and turn research into continuous improvement.']];let step=0;function showStep(i){step=i;secure.querySelector('h2').textContent=`0${i+1} / ${steps[i][0]}`;secure.querySelector('.secure-copy').textContent=steps[i][1];if(!secure.open)secure.showModal();}steps.forEach(([name],i)=>{const b=document.createElement('button');b.textContent=`${i+1} ${name}`;b.onclick=()=>showStep(i);terminal.insertBefore(b,terminal.querySelector('span'));});secure.querySelector('.secure-close').onclick=()=>secure.close();secure.querySelector('.secure-next').onclick=()=>showStep((step+1)%3);
const work=document.createElement('section');work.className='professional-update section-shell';work.innerHTML=`<p class="eyebrow">LEADERSHIP / COMMUNITY</p><h2>Responsibility,<br><em>beyond the screen.</em></h2><div class="professional-grid"><article><span>BUSINESS</span><h3>Company directorships</h3><p>Director of TRIP BHAI LTD and ESON SOFT IT LIMITED.</p><a href="https://find-and-update.company-information.service.gov.uk/company/16286072/officers" target="_blank" rel="noopener">Trip Bhai · official record ↗</a><a href="https://find-and-update.company-information.service.gov.uk/company/16999188/officers" target="_blank" rel="noopener">Eson Soft IT · official record ↗</a></article><article><span>CRICKET / ENGLAND</span><h3>Seasonal LMS umpire</h3><p>Last Man Stands match records identify ZR Saimon (LS) as an umpire. No estimated match total.</p><a href="https://www.lastmanstands.com/lms-cricket/match-centre/info/459959" target="_blank" rel="noopener">28 May 2025 · match record ↗</a><a href="https://www.lastmanstands.com/lms-cricket/match-centre/info/457013?fixtureid=457013" target="_blank" rel="noopener">29 April 2025 · match record ↗</a></article><article><span>PROFESSIONAL ARCHIVE</span><h3>A short chapter at NTV</h3><p>A brief period working at NTV, documented by the supplied personal photograph.</p><button id="ntvArchive">Open NTV photograph ↗</button></article></div>`;$('#research').before(work);$('#ntvArchive').onclick=()=>window.zrOpenGallery('NTV',extraArchive.NTV,'Professional archive');
const source=document.createElement('p');source.innerHTML='Sound design uses locally bundled <a href="https://opengameart.org/content/racing-car-engine-sound-loops" target="_blank" rel="noopener">CC0 engine recordings</a>, <a href="https://opengameart.org/content/rain-loopable" target="_blank" rel="noopener">CC0 rain</a> and <a href="https://kenney.nl/assets/impact-sounds" target="_blank" rel="noopener">Kenney CC0 effects</a>. Weather is a cinematic simulation, not a live forecast. The grand tourer and private jet are original stylised models, not personal vehicles.';$('#sourcesBody').append(source);
